#!/usr/bin/env python3
"""Tiny synthetic v11 metadata fixtures with independently hashed generated bytes.

No original assets, archive reads, device I/O, or large on-disk payloads.
The C test provider generates byte i as (17*i + 31*(i>>8) + 7*(i>>16) + 3) & 255.
Virtual .meta files contain physical header + metadata tail, not sparse archives.
Only zlib-small.pak contains a complete small archive.
"""
from pathlib import Path
import hashlib
import json
import struct
import sys
import zlib


def generated_bytes(start, count):
    return bytes((17*i + 31*(i >> 8) + 7*(i >> 16) + 3) & 255
                 for i in range(start, start + count))


def generated_sha1(count):
    digest = hashlib.sha1()
    for start in range(0, count, 65536):
        digest.update(generated_bytes(start, min(65536, count-start)))
    return digest.digest()


def fstring(text):
    value = text.encode('utf-8') + b'\0'
    return struct.pack('<i', len(value)) + value


def fixture(stored_size, decoded_size, method, stored_sha1, stored_bytes=None):
    header_size = 53 if method == 0 else 73
    physical = struct.pack('<QQQI', 0, stored_size, decoded_size, method) + stored_sha1
    if method:
        physical += struct.pack('<IQQ', 1, header_size, header_size+stored_size)
    physical += b'\0' + struct.pack('<I', 0 if method == 0 else decoded_size)
    if len(physical) != header_size:
        raise RuntimeError('physical header length')
    encoded = struct.pack('<III', 0xe0000000 if method == 0 else 0xe0800040,
                          0, decoded_size)
    if method:
        encoded += struct.pack('<I', stored_size)
    path_index = struct.pack('<iQi', 1, 0x123456789abcdef0, 0) + struct.pack('<i', 0)
    directory_index = (struct.pack('<i', 1) + fstring('') + struct.pack('<i', 1)
                       + fstring('deterministic.bin') + struct.pack('<i', 0))
    mount = fstring('/Synthetic/')
    primary_size = len(mount)+12+40+40+4+len(encoded)+4
    primary_offset = header_size+stored_size
    path_offset = primary_offset+primary_size
    directory_offset = path_offset+len(path_index)
    primary = mount+struct.pack('<iQ', 1, 0x12345678)
    primary += struct.pack('<IQQ', 1, path_offset, len(path_index))+hashlib.sha1(path_index).digest()
    primary += struct.pack('<IQQ', 1, directory_offset, len(directory_index))+hashlib.sha1(directory_index).digest()
    primary += struct.pack('<i', len(encoded))+encoded+struct.pack('<i', 0)
    if len(primary) != primary_size:
        raise RuntimeError('primary length')
    footer = bytes(16)+b'\0'+struct.pack('<IIQQ', 0x5a6f12e1, 11, primary_offset, len(primary))
    footer += hashlib.sha1(primary).digest()+b'Zlib'+bytes(28)+bytes(32*4)
    if len(footer) != 221:
        raise RuntimeError('footer length')
    tail = primary+path_index+directory_index+footer
    data = physical+(b'' if stored_bytes is None else stored_bytes)+tail
    return data, {'header_bytes': header_size, 'stored_bytes': stored_size,
                  'decoded_bytes': decoded_size, 'logical_bytes': primary_offset+len(tail),
                  'metadata_bytes': len(tail), 'stored_sha1': stored_sha1.hex(),
                  'provider': 'generated_exact_bytes' if stored_bytes is None else 'complete_small_archive'}


def main():
    if len(sys.argv) != 2:
        raise SystemExit('usage: generate_large_none_fixtures.py OUTPUT_DIRECTORY')
    out = Path(sys.argv[1])
    out.mkdir(parents=True, exist_ok=True)
    records = []
    cases = [('none-1048576.meta', 1048576), ('none-1048577.meta', 1048577),
             ('none-2742265.meta', 2742265), ('none-4194304.meta', 4194304),
             ('none-4194305.meta', 4194305)]
    for name, count in cases:
        data, record = fixture(count, count, 0, generated_sha1(count))
        (out/name).write_bytes(data)
        records.append({'name': name, 'file_bytes': len(data),
                        'sha256': hashlib.sha256(data).hexdigest(), **record})
    for name, stored, decoded in [('zlib-stored-over.meta', 1048577, 32),
                                  ('zlib-output-over.meta', 1, 1048577)]:
        data, record = fixture(stored, decoded, 1, generated_sha1(stored))
        (out/name).write_bytes(data)
        records.append({'name': name, 'file_bytes': len(data),
                        'sha256': hashlib.sha256(data).hexdigest(), **record})
    decoded = generated_bytes(0, 32)
    compressed = zlib.compress(decoded, 9)
    data, record = fixture(len(compressed), len(decoded), 1, hashlib.sha1(compressed).digest(), compressed)
    (out/'zlib-small.pak').write_bytes(data)
    records.append({'name': 'zlib-small.pak', 'file_bytes': len(data),
                    'sha256': hashlib.sha256(data).hexdigest(),
                    'decoded_sha1': hashlib.sha1(decoded).hexdigest(), **record})
    manifest = {'schema_version': 1, 'synthetic_only': True,
                'payload_formula': '(17*i + 31*(i>>8) + 7*(i>>16) + 3) & 255',
                'hash_oracle': 'Python hashlib over exact generated payload bytes',
                'compression_oracle': 'Python stdlib zlib '+zlib.ZLIB_RUNTIME_VERSION,
                'records': records}
    (out/'oracle.json').write_text(json.dumps(manifest, indent=2)+'\n')
    print(json.dumps({'fixtures': len(records), 'on_disk_bytes': sum(r['file_bytes'] for r in records),
                      'synthetic_only': True}, sort_keys=True))


if __name__ == '__main__':
    main()
